const EXPENSE_RULES=[['Aluguel',/\baluguel\b/],['Água',/\bagua\b/],['Luz',/\bluz\b/],['Internet',/\binternet\b/],['Segurança',/\bseguranca\b/],['Software',/\bsoftware\b|\bsistema\b/],['Ferramentas',/\bferramentas?\b/],['Combustível',/\bcombustivel\b/],['Manutenção',/\bmanutencao\b/],['Funcionário fixo',/\bfuncionario\b.*\bfixo\b|\bfixo\b.*\bfuncionario\b/],['Advogado',/\badvogad[oa]\b/],['Contador',/\bcontador(?:a)?\b|\bcontabilidade\b/],['Impostos',/\bimpostos?\b/],['Taxas',/\btaxas?\b/],['Cel',/\bcel\b|\bcelular\b/],['Compra materiais',/\bcompra(?: de)? materiais?\b/],['Mendonça',/\bmendonca\b/],['Gasolina',/\bgasolina\b/],['Limpeza',/\blimpeza\b/]];
const FIXED_MONTHLY_COSTS=new Map([['Aluguel',4000],['Água',52],['Luz',250],['Internet',170],['Segurança',190],['Software',500],['Ferramentas',2000],['Combustível',500],['Manutenção',1000],['Funcionário fixo',600],['Advogado',650],['Contador',450],['Impostos',270]]);
const expenseText=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const expenseKind=description=>EXPENSE_RULES.find(([,pattern])=>pattern.test(expenseText(description)))?.[0]||'';

const costPlanMonthLabel=value=>{const[y,m]=String(value).split('-').map(Number);return y&&m?new Date(y,m-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'}):value};
function costPlanRows(month=activeCostMonth){const savedByCategory=new Map(costPlans.filter(item=>item.month===month).map(item=>[item.category,item])),cashByCategory=new Map();for(const record of records){if(record.category!=='Fluxo de caixa'||record.status!=='Realizado'||record.kind!=='Saída'||String(record.dueDate||record.createdAt||'').slice(0,7)!==month)continue;const category=expenseKind(record.description);if(category)cashByCategory.set(category,(cashByCategory.get(category)||0)+Number(record.amount||0))}return EXPENSE_RULES.map(([category])=>{const saved=savedByCategory.get(category),planned=saved?Number(saved.planned)||0:(FIXED_MONTHLY_COSTS.get(category)||0),cashPaid=cashByCategory.get(category)||0,paid=Math.max(cashPaid,Number(saved?.paid)||0);return{category,planned,paid,actual:paid,cashPaid,difference:planned-paid,percent:planned>0?paid/planned*100:(paid>0?100:0)}})}
const costPlanEntries=(category,month=activeCostMonth)=>records.filter(record=>record.category==='Fluxo de caixa'&&record.status==='Realizado'&&record.kind==='Saída'&&String(record.dueDate||record.createdAt||'').slice(0,7)===month&&expenseKind(record.description)===category).sort((a,b)=>String(b.dueDate||b.createdAt||'').localeCompare(String(a.dueDate||a.createdAt||'')));
function openCostPlanDetails(category){document.querySelector('.cost-plan-detail-popup')?.remove();const items=costPlanEntries(category),total=items.reduce((sum,item)=>sum+Number(item.amount||0),0),row=costPlanRows().find(item=>item.category===category),popup=document.createElement('div');popup.className='check-popup finance-popup cost-plan-detail-popup';popup.innerHTML=`<div class="check-popup-card"><div class="finance-area-head"><div><span class="eyebrow">PLANO DE CUSTOS</span><h3>${esc(category)}</h3><p>Lançamentos registrados em ${esc(costPlanMonthLabel(activeCostMonth))}.</p></div><button type="button" class="secondary close-cost-details">Fechar</button></div><div class="finance-summary"><article><span>Valor pago no plano</span><b>${money(row?.paid)}</b></article><article><span>Registros encontrados</span><b>${items.length}</b></article><article class="finance-summary-total"><span>Localizado nos caixas</span><b>${money(total)}</b></article></div><div class="table-card finance-table cost-plan-detail-table"><table><thead><tr><th>Data</th><th>Caixa</th><th>Descrição</th><th>Valor</th></tr></thead><tbody>${items.length?items.map(item=>`<tr><td>${date(item.dueDate||localDateOnly(item.createdAt))}</td><td>${esc(cashAccount(item))}</td><td>${esc(item.description)}</td><td><b>${money(item.amount)}</b></td></tr>`).join(''):'<tr><td colspan="4">Nenhum lançamento registrado nesta categoria e neste mês.</td></tr>'}</tbody></table></div></div>`;const close=()=>{popup.remove();document.body.classList.remove('modal-open')};popup.querySelector('.close-cost-details').onclick=close;popup.onclick=event=>{if(event.target===popup)close()};document.body.append(popup);document.body.classList.add('modal-open')}
function costPlanAreaHtml(){const rows=costPlanRows(),planned=rows.reduce((sum,item)=>sum+item.planned,0),paid=rows.reduce((sum,item)=>sum+item.paid,0),difference=planned-paid,percent=planned>0?paid/planned*100:(paid>0?100:0);return`<div class="finance-area-head"><div><h3>Plano de custos</h3><p>Custos planejados e valores pagos em ${esc(costPlanMonthLabel(activeCostMonth))}. Clique em uma categoria para ver os registros encontrados nos caixas.</p></div><label><span>Mês</span><input id="costPlanMonth" type="month" value="${esc(activeCostMonth)}"></label></div><div class="finance-summary"><article><span>Total planejado</span><b>${money(planned)}</b></article><article><span>Total pago</span><b>${money(paid)}</b></article><article><span>Percentual pago</span><b>${percent.toLocaleString('pt-BR',{maximumFractionDigits:1})}%</b></article><article class="finance-summary-total"><span>Saldo a pagar</span><b>${money(difference)}</b></article></div><p class="archive-note">O valor pago considera o maior valor entre o total informado e os pagamentos identificados nos caixas, sem somar os dois. Informar um valor aqui não cria uma nova saída no caixa.</p><form id="costPlanForm"><div class="table-card finance-table"><table><thead><tr><th>Categoria</th><th>Planejado</th><th>Pago</th><th>Saldo</th><th>Percentual pago</th></tr></thead><tbody>${rows.map(item=>`<tr class="cost-plan-row" data-cost-category="${esc(item.category)}" tabindex="0" role="button" aria-label="Ver lançamentos de ${esc(item.category)}"><td><b>${esc(item.category)}</b><small>Toque para ver os registros</small></td><td><input class="cost-plan-value" type="number" min="0" step="0.01" inputmode="decimal" value="${item.planned.toFixed(2)}" aria-label="Valor planejado para ${esc(item.category)}"></td><td><input class="cost-plan-paid" type="number" min="0" step="0.01" inputmode="decimal" value="${item.paid.toFixed(2)}" aria-label="Valor pago de ${esc(item.category)}"></td><td><b>${money(item.difference)}</b></td><td>${item.percent.toLocaleString('pt-BR',{maximumFractionDigits:1})}%</td></tr>`).join('')}</tbody></table></div><button class="primary wide">Salvar valores do plano de custos</button></form>`}
function wireCostPlan(target){target.querySelector('#costPlanMonth').onchange=event=>{activeCostMonth=event.target.value||new Date().toISOString().slice(0,7);renderArea('Plano de custos')};target.querySelectorAll('[data-cost-category]').forEach(row=>{const open=event=>{if(event.target.closest('.cost-plan-value,.cost-plan-paid'))return;openCostPlanDetails(row.dataset.costCategory)};row.onclick=open;row.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open(event)}}});target.querySelector('#costPlanForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter,items=[...event.currentTarget.querySelectorAll('[data-cost-category]')].map(row=>({category:row.dataset.costCategory,planned:Number(row.querySelector('.cost-plan-value').value)||0,paid:Number(row.querySelector('.cost-plan-paid').value)||0}));button.disabled=true;button.textContent='Salvando…';try{costPlans=await saveCostPlan(activeCostMonth,items);renderArea('Plano de custos');alert('Valores planejados e pagos foram salvos.')}catch(error){button.disabled=false;button.textContent='Salvar valores do plano de custos';alert(error.message)}}}

function supplierAreaHtml(){const week=workWeek(localDateOnly(new Date())),luizinhoTotal=currentLuizinhoTotal(),retificaTotal=retificaBalance();if(activeSupplier==='luizinho'){const rows=[...supplierSettlements.luizinho].sort((a,b)=>String(b.date).localeCompare(String(a.date)));return`<div class="finance-area-head"><div><h3>Acerto fornecedores</h3><p>Notas por itens do Luizinho integradas ao estoque.</p></div><button class="primary add-supplier">＋ Incluir nota</button></div><div class="cash-account-tabs supplier-tabs"><button data-supplier="luizinho" class="active">Acerto Luizinho</button><button data-supplier="retifica">Acerto Retífica</button></div><div class="finance-summary"><article><span>Notas desta semana</span><b>${money(luizinhoTotal)}</b><small>${date(week.start)} a ${date(week.end)}</small></article><article class="finance-summary-total"><span>Vencimento do acerto</span><b>${date(nextSupplierMonday(week.start))}</b><small>Conta a pagar gerada automaticamente</small></article></div><div class="table-card finance-table supplier-table"><table><thead><tr><th>Data</th><th>Itens</th><th>Veículo</th><th>Valor total</th><th></th></tr></thead><tbody>${rows.length?rows.map(item=>`<tr><td>${date(item.date)}</td><td><b>${esc(item.description)}</b><small>${item.items?.length?`${item.items.length} item(ns) · ${item.items.map(part=>`${part.quantity}× ${part.code||'sem código'}`).join(' · ')}`:'Nota anterior sem itens detalhados'}</small></td><td>${esc(item.vehicle||'—')}</td><td><b>${money(item.amount)}</b></td><td><div class="finance-row-actions"><button class="secondary edit-supplier" data-id="${item.id}">Editar</button><button class="danger delete-supplier" data-id="${item.id}">Excluir</button></div></td></tr>`).join(''):'<tr><td colspan="5">Nenhuma nota do Luizinho lançada.</td></tr>'}</tbody></table></div>`}const chronological=[...supplierSettlements.retifica].sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.createdAt).localeCompare(String(b.createdAt)));let balance=0;chronological.forEach(item=>item.balance=balance+=Number(item.debit||0)-Number(item.paid||0));const rows=[...chronological].reverse();return`<div class="finance-area-head"><div><h3>Acerto fornecedores</h3><p>Conta-corrente de valores devidos e pagos à Retífica.</p></div><button class="primary add-supplier">＋ Incluir movimento</button></div><div class="cash-account-tabs supplier-tabs"><button data-supplier="luizinho">Acerto Luizinho</button><button data-supplier="retifica" class="active">Acerto Retífica</button></div><div class="finance-summary"><article class="finance-summary-total"><span>Saldo devedor da Retífica</span><b>${money(retificaTotal)}</b><small>Considerado na saúde da empresa</small></article></div><div class="table-card finance-table supplier-table"><table><thead><tr><th>Data</th><th>Descrição</th><th>Veículo</th><th>Valor devedor</th><th>Valor pago</th><th>Saldo</th><th></th></tr></thead><tbody>${rows.length?rows.map(item=>`<tr><td>${date(item.date)}</td><td><b>${esc(item.description)}</b></td><td>${esc(item.vehicle||'—')}</td><td>${item.debit?money(item.debit):'—'}</td><td>${item.paid?money(item.paid):'—'}</td><td><b>${money(item.balance)}</b></td><td><div class="finance-row-actions"><button class="secondary edit-supplier" data-id="${item.id}">Editar</button><button class="danger delete-supplier" data-id="${item.id}">Excluir</button></div></td></tr>`).join(''):'<tr><td colspan="7">Nenhum movimento da Retífica lançado.</td></tr>'}</tbody></table></div>`}
function nextSupplierMonday(weekStart){const value=new Date(`${weekStart}T12:00:00`);value.setDate(value.getDate()+7);return localDateOnly(value)}
function luizinhoLedger(){const weeks=new Map();for(const note of supplierSettlements.luizinho){const week=workWeek(note.date),entry=weeks.get(week.start)||{...week,notes:[],returns:[],gross:0,credit:0,total:0};entry.notes.push(note);entry.gross+=Number(note.amount||0);weeks.set(week.start,entry)}for(const item of supplierSettlements.luizinhoReturns||[]){const week=workWeek(item.creditWeek),entry=weeks.get(week.start)||{...week,notes:[],returns:[],gross:0,credit:0,total:0};entry.returns.push(item);entry.credit+=Number(item.amount||0);weeks.set(week.start,entry)}for(const entry of weeks.values())entry.total=Math.max(0,Number((entry.gross-entry.credit).toFixed(2)));const payments=records.filter(item=>item.category==='Fluxo de caixa'&&item.status==='Realizado'&&item.kind==='Saída'),allocated=allocateLuizinhoPayments(weeks.values(),payments).weeks;for(const week of allocated)week.payments=week.payments.map(({payment,amount})=>({...payment,amount}));return allocated.sort((a,b)=>b.start.localeCompare(a.start))}
function separateLuizinhoWeeks(target){const table=target.querySelector('.supplier-table table'),body=table?.querySelector('tbody'),rows=[...(body?.querySelectorAll('.view-luizinho-note')||[])];if(!table||!body||!rows.length)return;table.classList.add('luizinho-week-grouped');const selected=luizinhoLedger().filter(week=>showLuizinhoArchive?week.settled:!week.settled);for(const week of selected){const label=`${date(week.start)} a ${date(week.end)}`,first=rows.find(row=>row.cells[0]?.textContent.trim()===label);if(!first)continue;const heading=document.createElement('tr');heading.className='luizinho-week-heading';heading.innerHTML=`<td colspan="7"><div><b>Semana: ${esc(label)}</b><span>Notas brutas: <strong>${money(week.gross)}</strong></span>${week.credit?`<span>Créditos: <strong>− ${money(week.credit)}</strong></span>`:''}<span>Total das notas: <strong>${money(week.total)}</strong></span><span>Pago: <strong>${money(week.paid)}</strong></span><span>${week.settled?'Quitada':'Saldo'}: <strong>${week.settled?'✓':money(week.balance)}</strong></span></div></td>`;body.insertBefore(heading,first)}}
const supplierAreaHtmlWithoutLuizinhoPayments=supplierAreaHtml;
supplierAreaHtml=function(){if(activeSupplier!=='luizinho')return supplierAreaHtmlWithoutLuizinhoPayments();const ledger=luizinhoLedger(),open=ledger.filter(item=>!item.settled),archived=ledger.filter(item=>item.settled),selected=showLuizinhoArchive?archived:open,notes=selected.flatMap(week=>week.notes.map(note=>({...note,week}))).sort((a,b)=>String(b.date).localeCompare(String(a.date))),payments=selected.flatMap(week=>week.payments.map(payment=>({payment,week}))).sort((a,b)=>String(b.payment.dueDate||'').localeCompare(String(a.payment.dueDate||''))),total=selected.reduce((sum,item)=>sum+item.total,0),paid=selected.reduce((sum,item)=>sum+item.paid,0),balance=selected.reduce((sum,item)=>sum+item.balance,0);return`<div class="finance-area-head"><div><h3>Acerto fornecedores</h3><p>Notas por itens do Luizinho integradas ao estoque.</p></div><button class="primary add-supplier">＋ Incluir nota</button></div><div class="cash-account-tabs supplier-tabs"><button data-supplier="luizinho" class="active">Acerto Luizinho</button><button data-supplier="retifica">Acerto Retífica</button></div><div class="cash-account-tabs supplier-period-tabs"><button data-luizinho-archive="open" class="${showLuizinhoArchive?'':'active'}">Em aberto</button><button data-luizinho-archive="paid" class="${showLuizinhoArchive?'active':''}">Pagas e arquivadas</button></div><div class="finance-summary"><article><span>Total das notas</span><b>${money(total)}</b></article><article><span>Valor pago</span><b>${money(paid)}</b></article><article class="finance-summary-total"><span>Saldo devedor</span><b>${money(balance)}</b><small>Pagamento desta semana abate a semana anterior</small></article></div><div class="table-card finance-table supplier-table"><table><thead><tr><th>Semana</th><th>Data</th><th>Itens</th><th>Veículo</th><th>Valor</th><th>Situação</th><th></th></tr></thead><tbody>${notes.length?notes.map(item=>`<tr class="view-luizinho-note" data-note-id="${item.id}" tabindex="0"><td>${date(item.week.start)} a ${date(item.week.end)}</td><td>${date(item.date)}</td><td><b>${esc(item.description)}</b><small>${item.items?.length?`${item.items.length} item(ns) · ${item.items.map(part=>`${part.quantity}× ${part.code||'sem código'}`).join(' · ')}`:'Nota anterior sem itens detalhados'}</small></td><td>${esc(item.vehicle||'—')}</td><td><b>${money(item.amount)}</b></td><td><span class="status ${item.week.settled?'done':'pending'}">${item.week.settled?'Paga · Arquivada':`Em aberto · ${money(item.week.balance)}`}</span></td><td><div class="finance-row-actions"><button class="secondary edit-supplier" data-id="${item.id}">Editar</button><button class="danger delete-supplier" data-id="${item.id}">Excluir</button></div></td></tr>`).join(''):'<tr><td colspan="7">Nenhuma semana nesta situação.</td></tr>'}</tbody></table></div><h4>Pagamentos identificados</h4><div class="table-card finance-table supplier-payment-table"><table><thead><tr><th>Data do pagamento</th><th>Semana quitada</th><th>Caixa</th><th>Descrição</th><th>Valor pago</th></tr></thead><tbody>${payments.length?payments.map(({payment,week})=>`<tr><td>${date(payment.dueDate)}</td><td>${date(week.start)} a ${date(week.end)}</td><td>${esc(cashAccount(payment))}</td><td>${esc(payment.description)}</td><td><b>${money(payment.amount)}</b></td></tr>`).join(''):'<tr><td colspan="5">Nenhum pagamento identificado neste período.</td></tr>'}</tbody></table></div>`}
function luizinhoItemRow(item={},index=0){const quantity=Math.max(1,Number(item.quantity||1)),unitValue=Math.max(0,Number(item.unitValue||0));return`<tr data-note-item="${index}"><td class="note-code" data-label="Código"><input data-note-field="code" value="${esc(item.code||'')}" placeholder="Código"></td><td class="note-brand" data-label="Marca"><input data-note-field="brand" value="${esc(item.brand||'')}" placeholder="Marca"></td><td class="note-quantity" data-label="Quantidade"><input data-note-field="quantity" type="number" min="1" step="1" value="${quantity}"></td><td class="note-description" data-label="Descrição"><input data-note-field="description" value="${esc(item.description||'')}" placeholder="Descrição"></td><td class="note-unit" data-label="Valor unitário"><input data-note-field="unitValue" type="number" min="0.01" step="0.01" value="${unitValue||''}"></td><td class="note-total-cell" data-label="Valor total"><b data-note-total>${money(quantity*unitValue)}</b></td><td class="note-remove"><button type="button" class="remove-line remove-note-item" aria-label="Remover item">×</button></td></tr>`}
