function expensesAreaHtml(){const reserveEntries=cashProfitEvents().map(item=>({date:item.date,kind:'Entrada',category:'Reserva para despesas',description:`Reserva de 30% do lucro recebido da O.S. #${item.order.number}`,amount:item.reserve,source:`O.S. #${item.order.number}`})).filter(item=>item.amount>0),expenseEntries=records.filter(record=>record.category==='Fluxo de caixa'&&record.status==='Realizado'&&record.kind==='Saída'&&expenseKind(record.description)).map(record=>({date:record.dueDate||localDateOnly(record.createdAt),kind:'Saída',category:expenseKind(record.description),description:record.description,amount:Number(record.amount||0),source:cashAccount(record)})),chronological=[...reserveEntries,...expenseEntries].sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))||a.kind.localeCompare(b.kind));let balance=0;chronological.forEach(item=>item.balance=balance+=item.kind==='Entrada'?item.amount:-item.amount);const entries=reserveEntries.reduce((sum,item)=>sum+item.amount,0),exits=expenseEntries.reduce((sum,item)=>sum+item.amount,0),rows=[...chronological].reverse();return`<div class="finance-area-head"><div><h3>Despesas</h3><p>30% do lucro real recebido como entrada e despesas identificadas nos caixas como saída.</p></div></div><div class="finance-summary"><article><span>Reserva · 30% do lucro recebido</span><b>${money(entries)}</b></article><article><span>Despesas identificadas</span><b>${money(exits)}</b></article><article class="finance-summary-total"><span>Saldo disponível</span><b>${money(entries-exits)}</b></article></div><p class="archive-note">Palavras identificadas: ${EXPENSE_RULES.map(([label])=>label).join(' · ')}</p><div class="table-card finance-table partner-commission-table expense-ledger-table"><table><thead><tr><th>Data</th><th>Movimento</th><th>Classificação</th><th>Origem</th><th>Descrição</th><th>Entrada</th><th>Saída</th><th>Saldo</th></tr></thead><tbody>${rows.length?rows.map(item=>`<tr><td>${date(item.date)}</td><td><b>${item.kind}</b></td><td>${esc(item.category)}</td><td>${esc(item.source)}</td><td>${esc(item.description)}</td><td>${item.kind==='Entrada'?money(item.amount):'—'}</td><td>${item.kind==='Saída'?money(item.amount):'—'}</td><td><b>${money(item.balance)}</b></td></tr>`).join(''):'<tr><td colspan="8">Nenhuma reserva ou despesa identificada.</td></tr>'}</tbody></table></div>`}
function balancePayableWindow(value=localDateOnly(new Date())){const week=workWeek(value),saturday=new Date(`${week.start}T12:00:00`);saturday.setDate(saturday.getDate()-2);return{start:localDateOnly(saturday),end:week.end}}
function payableForBalance(record,value=localDateOnly(new Date())){if(record.category!=='Conta a pagar'||record.status==='Realizado'||!record.dueDate)return false;const currentWeek=workWeek(value),luizinhoWeek=String(record.reference||'').match(/^acerto-luizinho-(\d{4}-\d{2}-\d{2})$/)?.[1];if(luizinhoWeek)return luizinhoWeek<=currentWeek.start;const due=String(record.dueDate).slice(0,10),range=balancePayableWindow(value);return due<range.start||(due>=range.start&&due<=range.end)}
function totals(){const orders=localOrders(),receivable=records.filter(r=>readyReceivable(r,orders)&&r.status!=='Realizado').reduce((s,r)=>s+r.amount,0),payable=records.filter(record=>payableForBalance(record)).reduce((s,r)=>s+r.amount,0),commissions=mechanicCommissionState().total,bb=cashBalance('Banco do Brasil'),ml=cashBalance('Mercado Livre'),cash=cashBalance('Dinheiro'),balance=bb+ml+cash;return{receivable,payable,commissions,bb,ml,cash,balance,balanceSheet:balance+receivable-payable-commissions}}
const totalsWithoutPartnerCommissions=totals;
totals=function(){const result=totalsWithoutPartnerCommissions(),mechanicCommissions=result.commissions,partnerCommissions=currentPartnerCommissions();return{...result,mechanicCommissions,partnerCommissions,commissions:mechanicCommissions+partnerCommissions,balanceSheet:result.balanceSheet-partnerCommissions}};

function remainingFixedCommitments(month){
  const includedByCategory=new Map();
  for(const record of records){
    // Only offset bills already counted in payables for this same month.
    if(!payableForBalance(record)||String(record.dueDate||'').slice(0,7)!==month)continue;
    const category=expenseKind(record.description);
    if(category)includedByCategory.set(category,(includedByCategory.get(category)||0)+Math.max(0,Number(record.amount||0)));
  }
  return costPlanRows(month).map(item=>({...item,difference:Math.max(0,item.difference-(includedByCategory.get(item.category)||0))}));
}

function companyHealth(){
  const total=totals(),month=new Date().toISOString().slice(0,7),plan=remainingFixedCommitments(month),remainingFixed=plan.reduce((sum,item)=>sum+item.difference,0),cashMonth=records.filter(record=>record.category==='Fluxo de caixa'&&record.status==='Realizado'&&String(record.dueDate||record.createdAt||'').slice(0,7)===month),inflows=cashMonth.filter(record=>record.kind==='Entrada').reduce((sum,record)=>sum+Number(record.amount||0),0),outflows=cashMonth.filter(record=>record.kind==='Saída').reduce((sum,record)=>sum+Number(record.amount||0),0),monthlyResult=inflows-outflows,retifica=Math.max(0,retificaBalance()),resources=Math.max(0,total.balance)+Math.max(0,total.receivable),commitments=Math.max(0,total.payable)+Math.max(0,total.commissions)+remainingFixed+retifica,coverage=commitments>0?resources/commitments:resources>0?2:1,coveragePoints=Math.min(70,Math.max(0,coverage/1.5*70)),cashPoints=monthlyResult>=0?30:Math.max(0,30-(Math.abs(monthlyResult)/Math.max(inflows,1))*30),score=Math.round(coveragePoints+cashPoints),level=score>=80?'Saudável':score>=60?'Estável':score>=40?'Atenção':'Crítica',tone=score>=80?'healthy':score>=60?'stable':score>=40?'attention':'critical';
  return{score,level,tone,resources,commitments,coverage,monthlyResult,remainingFixed,retifica,inflows,outflows,payable:Math.max(0,total.payable),mechanicCommissions:Math.max(0,total.mechanicCommissions),partnerCommissions:Math.max(0,total.partnerCommissions)}
}
function openBalanceDetails(){
  const total=totals(),items=[
    ['Banco do Brasil',total.bb,1],
    ['Mercado Livre',total.ml,1],
    ['Dinheiro',total.cash,1],
    ['Contas a receber · O.S. prontas',total.receivable,1],
    ['Contas a pagar vencidas ou desta semana',total.payable,-1],
    ['Comissões da equipe',total.mechanicCommissions,-1],
    ['Comissões dos sócios',total.partnerCommissions,-1]
  ];
  document.querySelector('.balance-details-popup')?.remove();
  const popup=document.createElement('div');
  popup.className='check-popup finance-popup balance-details-popup';
  popup.innerHTML=`<div class="check-popup-card"><span class="eyebrow">DETALHAMENTO FINANCEIRO</span><h3>Composição do balanço</h3><p>Valores positivos aumentam o balanço; compromissos diminuem.</p><div class="table-card finance-table balance-details-table"><table><thead><tr><th>Item</th><th>Operação</th><th>Valor</th></tr></thead><tbody>${items.map(([label,value,sign])=>`<tr><td>${esc(label)}</td><td class="balance-operation ${sign>0?'positive':'negative'}">${sign>0?'+':'−'}</td><td><b>${money(value)}</b></td></tr>`).join('')}<tr class="company-commitments-total"><td><b>Balanço atual</b></td><td>=</td><td><b>${money(total.balanceSheet)}</b></td></tr></tbody></table></div><small class="balance-details-formula">Caixas + contas a receber − contas a pagar − comissões da equipe − comissões dos sócios</small><button type="button" class="primary wide close-balance-details">Fechar</button></div>`;
  const close=()=>popup.remove();
  popup.querySelector('.close-balance-details').onclick=close;
  popup.onclick=event=>{if(event.target===popup)close()};
  document.body.append(popup);
}
