function commissionPeopleRows(group){if(group==='partners')return Object.keys(PARTNER_DISPLAY_RATES).map(name=>({name,amount:partnerCommissionLedger(name).outstandingTotal}));const names=new Map();for(const name of[...activeMechanics(),...records.filter(record=>record.category==='Comissões').map(record=>record.mechanic).filter(Boolean)]){const key=normalizeCommissionText(name);if(key&&!names.has(key))names.set(key,name)}return[...names.values()].map(name=>({name,amount:mechanicCommissionState(name).total})).sort((a,b)=>a.name.localeCompare(b.name))}
