function commissionMechanicDetails(name){const state=mechanicCommissionState(name),rows=state.pending.map(record=>({date:String(record.dueDate||record.weekStart||record.createdAt||'').slice(0,10),week:commissionWeek(record.weekStart||record.dueDate),description:record.description||'Comissão gerada',generated:Number(record.amount||0),deduction:0}));let remaining=state.applied;for(const advance of state.advances){const deduction=Math.min(Number(advance.amount||0),remaining);if(deduction>0)rows.push({date:String(advance.dueDate||advance.createdAt||'').slice(0,10),week:commissionWeek(advance.dueDate||advance.createdAt),description:advance.description||'Vale / adiantamento',generated:0,deduction});remaining-=deduction;if(remaining<=0)break}rows.sort((a,b)=>a.date.localeCompare(b.date)||a.description.localeCompare(b.description));let balance=0;return rows.map(row=>({...row,balance:balance+=row.generated-row.deduction}))}
