function companyHealthHtml(){const health=companyHealth();return`<section class="company-health company-health-${health.tone}"><div class="company-health-head"><div><span class="eyebrow">SAÚDE DA EMPRESA</span><h3>${health.level}</h3><p>Capacidade financeira calculada com os dados atuais do aplicativo.</p></div><strong>${health.score}<small>/100</small></strong></div><progress max="100" value="${health.score}" aria-label="Saúde da empresa: ${health.score} de 100"></progress><div class="finance-summary"><article><span>Recursos disponíveis</span><b>${money(health.resources)}</b><small>Caixas + valores a receber</small></article><article class="company-health-commitments" role="button" tabindex="0"><span>Compromissos previstos</span><b>${money(health.commitments)}</b><small>Clique para ver cada compromisso</small></article><article><span>Saldo devedor da Retífica</span><b>${money(health.retifica)}</b><small>Incluído nos compromissos</small></article><article><span>Cobertura financeira</span><b>${health.coverage.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}×</b><small>Recursos ÷ compromissos</small></article><article><span>Resultado de caixa do mês</span><b>${money(health.monthlyResult)}</b><small>Entradas − saídas realizadas</small></article></div><small class="company-health-method">A nota atribui até 70 pontos à cobertura dos compromissos e até 30 pontos ao resultado mensal. Custos fixos padrão: ${money([...FIXED_MONTHLY_COSTS.values()].reduce((sum,value)=>sum+value,0))} por mês.</small></section>`}
function commitmentRows(type){const health=companyHealth(),month=new Date().toISOString().slice(0,7);let title='',total=0,rows=[];if(type==='payable'){title='Contas a pagar vencidas ou previstas';total=health.payable;rows=records.filter(record=>payableForBalance(record)).map(record=>({date:record.dueDate,description:record.description,amount:Number(record.amount||0)}))}else if(type==='mechanics'){const state=mechanicCommissionState();title='Comissões dos mecânicos';total=health.mechanicCommissions;rows=records.filter(record=>record.category==='Comissões'&&record.status!=='Realizado').map(record=>({date:record.dueDate,description:`${record.mechanic||'Mecânico'} · ${record.description}`,amount:Number(record.amount||0)}));let remaining=state.applied;for(const record of state.advances){const amount=Math.min(Number(record.amount||0),remaining);if(amount>0)rows.push({date:record.dueDate,description:`Vale descontado · ${record.advanceMechanic} · ${record.description}`,amount:-amount});remaining-=amount}}else if(type==='partners'){title='Comissões dos sócios';total=health.partnerCommissions;rows=Object.keys(PARTNER_DISPLAY_RATES).flatMap(partner=>partnerCommissionLedger(partner).open.map(item=>({date:item.date,description:`${partner} · O.S. #${item.order.number} · saldo em aberto`,amount:item.remaining})))}else if(type==='fixed'){title='Custos fixos restantes no mês';total=health.remainingFixed;rows=remainingFixedCommitments(month).filter(item=>item.difference>0).map(item=>({date:`${month}-01`,description:item.category,amount:item.difference}))}else{title='Saldo devedor da Retífica';total=health.retifica;rows=supplierSettlements.retifica.map(item=>({date:item.date,description:`${item.description}${item.vehicle?` · ${item.vehicle}`:''}`,amount:Number(item.debit||0)-Number(item.paid||0)}))}const listed=rows.reduce((sum,item)=>sum+item.amount,0),adjustment=total-listed;if(Math.abs(adjustment)>.009)rows.push({date:'',description:'Ajuste aplicado pelo indicador',amount:adjustment});return{title,total,rows:rows.sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')))}}
function openCompanyCommitmentList(type){const detail=commitmentRows(type);document.querySelector('.company-health-popup')?.remove();const popup=document.createElement('div');popup.className='check-popup finance-popup company-health-popup';popup.innerHTML=`<div class="check-popup-card"><span class="eyebrow">DETALHAMENTO DO COMPROMISSO</span><h3>${esc(detail.title)}</h3><p>Todos os registros que formam este valor.</p><div class="table-card finance-table company-commitments-table company-commitment-list"><table><thead><tr><th>Data</th><th>Registro</th><th>Valor</th></tr></thead><tbody>${detail.rows.length?detail.rows.map(item=>`<tr><td>${item.date?date(item.date):'—'}</td><td>${esc(item.description)}</td><td><b>${money(item.amount)}</b></td></tr>`).join(''):'<tr><td colspan="3">Nenhum registro compõe este compromisso.</td></tr>'}<tr class="company-commitments-total"><td colspan="2"><b>Total do compromisso</b></td><td><b>${money(detail.total)}</b></td></tr></tbody></table></div><div class="check-popup-actions"><button type="button" class="secondary back-company-commitments">Voltar</button><button type="button" class="primary close-company-commitments">Fechar</button></div></div>`;popup.querySelector('.back-company-commitments').onclick=openCompanyCommitments;popup.querySelector('.close-company-commitments').onclick=()=>popup.remove();popup.onclick=event=>{if(event.target===popup)popup.remove()};document.body.append(popup)}
