function dashboardHtml(){const total=totals(),lastBackup=localStorage.getItem('cortez-garage-last-backup')||'',backupDue=!lastBackup||Date.now()-new Date(lastBackup).getTime()>7*86400000;return`<div class="admin-head"><div><span class="eyebrow">GESTÃO FINANCEIRA NO BANCO</span><h2>Financeiro</h2>${lastBackup?`<small class="${backupDue?'backup-warning':''}">Última cópia: ${new Date(lastBackup).toLocaleString('pt-BR')}${backupDue?' · backup semanal pendente':''}</small>`:'<small class="backup-warning">Backup semanal pendente neste aparelho.</small>'}</div><div class="finance-row-actions admin-backup-actions"><button class="${backupDue?'danger':'secondary'}" id="createBackup">⇩ ${backupDue?'Criar backup semanal':'Criar backup'}</button><button class="secondary" id="restoreBackup">⇧ Restaurar backup</button><input id="restoreBackupFile" type="file" accept="application/json,.json" hidden><button class="secondary" id="manageUsers">Gerenciar usuários</button><button class="primary" id="addMechanic">＋ Adicionar mecânico</button></div></div><div class="finance-summary"><article><span>Contas a receber · O.S. prontas</span><b>${money(total.receivable)}</b></article><article><span>Contas a pagar</span><b>${money(total.payable)}</b></article><article><span>Banco do Brasil</span><b>${money(total.bb)}</b></article><article><span>Mercado Livre</span><b>${money(total.ml)}</b></article><article><span>Dinheiro</span><b>${money(total.cash)}</b></article><article class="finance-summary-total"><span>Saldo total em caixa</span><b>${money(total.balance)}</b></article><article class="commission-total-card" role="button" tabindex="0" aria-label="Ver comissões separadas"><span>Total de comissões a pagar</span><b>${money(total.commissions)}</b><small>Sócios + mecânicos · Clique para detalhar</small></article><article class="finance-summary-total finance-balance-sheet" role="button" tabindex="0" aria-label="Ver composição do balanço"><span>Balanço</span><b>${money(total.balanceSheet)}</b><small>Caixas + a receber − contas a pagar − comissões · Clique para detalhar</small></article></div><div class="home-menu finance-home-menu"><button data-finance-area="Fluxo de caixa"><i>R$</i><span>Caixa</span></button><button data-finance-area="Conta a pagar"><i>−</i><span>Contas a pagar</span></button><button data-finance-area="Conta a receber"><i>＋</i><span>Contas a receber</span></button><button data-finance-area="Comissões"><i>%</i><span>Comissões</span></button></div><section id="financeArea"></section>`}
