const renderAreaWithoutProfit=renderArea;
async function exportFinancePreview(button,modal,title,print=false){const original=button.textContent;button.disabled=true;button.textContent='Gerando PDF…';try{await exportReportPdf(modal.querySelector('.report-pdf-sheet'),title,{print})}catch(error){alert(`Não foi possível gerar o PDF.\n\n${error.message}`)}finally{button.disabled=false;button.textContent=original}}
function financePdfPreview(title,target){document.querySelector('.finance-profit-pdf')?.remove();const content=target.cloneNode(true);content.querySelector('.partner-tabs')?.remove();content.querySelector('.partner-period-tabs')?.remove();content.querySelectorAll('button').forEach(button=>button.remove());const modal=document.createElement('div');modal.className='report-pdf-preview finance-profit-pdf';modal.innerHTML=`<div class="report-pdf-sheet"><header><div class="report-company"><img src="${new URL('../official-logo.png',import.meta.url).href}" alt="Logo Cortez Garage"><div><h2>Cortez Garage mecânica e auto elétrica</h2><p>Av. Brasil, 5452, Bamerindus, Itapoá - SC</p><p>Cel: (47) 99124-7442 · CNPJ 57.757.919/0001-41</p></div></div><div><span>RELATÓRIO FINANCEIRO</span><h1>${esc(title)}</h1><p>Gerado em ${new Date().toLocaleString('pt-BR')}</p></div></header><main>${content.innerHTML}</main><footer><button class="secondary close-finance-pdf">Voltar</button><button class="secondary print-finance-pdf">Imprimir PDF</button><button class="primary save-finance-pdf">Salvar PDF</button></footer></div>`;modal.querySelector('.close-finance-pdf').onclick=()=>modal.remove();modal.querySelector('.print-finance-pdf').onclick=event=>exportFinancePreview(event.currentTarget,modal,title,true);modal.querySelector('.save-finance-pdf').onclick=event=>exportFinancePreview(event.currentTarget,modal,title);document.body.append(modal)}
function financePdfTitle(area){if(area==='Fluxo de caixa')return`Caixa — ${activeCashAccount}`;if(area==='Comissões')return`Comissões — ${activeMechanic}`;if(area==='Lucro')return'Lucro real e líquido';if(area==='Comissões sócios')return`Comissões dos sócios — ${activePartner} — ${partnerArchive?'Semanas arquivadas':'Semana atual'}`;if(area==='Plano de custos')return`Plano de custos — ${costPlanMonthLabel(activeCostMonth)}`;return area}function wireFinancePdf(area,target){const head=target.querySelector('.finance-area-head');if(!head||head.querySelector('.finance-area-pdf'))return;const button=document.createElement('button');button.type='button';button.className='primary finance-area-pdf';button.textContent='Imprimir PDF';button.onclick=()=>financePdfPreview(financePdfTitle(area),target);head.append(button)}
function commissionConfirmationHistoryHtml(){const rows=commissionConfirmations.filter(item=>String(item.mechanic||'').toLowerCase()===activeMechanic.toLowerCase());return`<section class="commission-closing-history"><div class="finance-area-head"><div><h3>Histórico do fechamento de comissões</h3><p>Confirmações registradas por ${esc(activeMechanic)}.</p></div></div><div class="table-card finance-table"><table><thead><tr><th>Semana</th><th>Mecânico</th><th>Usuário</th><th>Conferido em</th><th>Status</th></tr></thead><tbody>${rows.length?rows.map(item=>`<tr><td><b>${date(item.weekStart)} a ${date(friday(item.weekStart))}</b></td><td>${esc(item.mechanic)}</td><td>${esc(item.email)}</td><td>${new Date(item.confirmedAt).toLocaleString('pt-BR')}</td><td><span class="badge">Conferido</span></td></tr>`).join(''):'<tr><td colspan="5">Nenhuma conferência registrada para este mecânico.</td></tr>'}</tbody></table></div></section>`}
renderArea=function(area=activeArea){if(!['Lucro','Comissões sócios','Despesas','Plano de custos','Acerto fornecedores'].includes(area)){const result=renderAreaWithoutProfit(area),target=$('#financeArea');if(target&&area==='Comissões')target.insertAdjacentHTML('beforeend',commissionConfirmationHistoryHtml());if(target)wireFinancePdf(area,target);return result}activeArea=area;document.querySelectorAll('[data-finance-area]').forEach(button=>button.classList.toggle('active',button.dataset.financeArea===area));const target=$('#financeArea');if(!target)return;if(area==='Lucro'){target.innerHTML=profitAreaHtml();wireFinancePdf(area,target);return}if(area==='Despesas'){target.innerHTML=expensesAreaHtml();wireFinancePdf(area,target);return}if(area==='Plano de custos'){target.innerHTML=costPlanAreaHtml();wireCostPlan(target);wireFinancePdf(area,target);return}if(area==='Acerto fornecedores'){target.innerHTML=supplierAreaHtml();wireSupplierArea(target);wireFinancePdf(area,target);return}target.innerHTML=partnerCommissionsHtml(activePartner);target.querySelectorAll('[data-partner]').forEach(button=>button.onclick=()=>{activePartner=button.dataset.partner;renderArea('Comissões sócios')});target.querySelectorAll('[data-partner-archive]').forEach(button=>button.onclick=()=>{partnerArchive=button.dataset.partnerArchive==='archived';renderArea('Comissões sócios')});wireFinancePdf(area,target)};
async function removeFinance(id){const record=records.find(item=>item.id===id);if(!record||!confirm(`Excluir "${record.description}" no valor de ${money(record.amount)}?`))return;try{await deleteFinanceRecord(id);await loadDashboard()}catch(error){alert(error.message)}}
function confirmLuizinhoSettlement(description,amount,editing=false){if(!isLuizinhoPaymentDescription(description))return undefined;const text=String(description||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();if(/\bacerto\b/.test(text)&&/\bluizinho\b/.test(text))return true;if(confirm(`Pagamento Luizinho de ${money(amount)}.\n\nEste valor é referente ao acerto Luizinho?\n\nOK: dar baixa no acerto da semana anterior.\nCancelar: não dar baixa no acerto.`))return true;if(!editing&&confirm('É uma conta antiga já cadastrada em Contas a pagar?\n\nOK: cancelar este lançamento e pagar pela aba Contas a pagar, que registra a saída no caixa.\nCancelar: salvar somente no caixa, sem baixar nenhuma conta.'))return null;return false}
function openCashEditPopup(id){const record=records.find(item=>item.id===id);if(!record)return;document.querySelector('.finance-popup')?.remove();const popup=document.createElement('div');popup.className='check-popup finance-popup';popup.innerHTML=`<form class="check-popup-card"><span class="eyebrow">EDITAR LANÇAMENTO</span><h3>${esc(cashAccount(record))}</h3><label><span>Caixa</span><select id="editFinanceAccount">${CASH_ACCOUNTS.map(name=>`<option ${name===cashAccount(record)?'selected':''}>${name}</option>`).join('')}</select></label><label><span>Data</span><input id="editFinanceDate" type="date" value="${esc(record.dueDate)}" required></label><label><span>Descrição</span><input id="editFinanceDescription" value="${esc(record.description)}" required></label><label><span>Valor</span><input id="editFinanceAmount" type="number" min="0.01" step="0.01" value="${Number(record.amount)}" required></label><label><span>Tipo</span><select id="editFinanceKind"><option ${record.kind==='Entrada'?'selected':''}>Entrada</option><option ${record.kind==='Saída'?'selected':''}>Saída</option></select></label><small id="editFinanceAutoKind" hidden>Classificado automaticamente como Saída.</small><div class="check-popup-actions"><button type="button" class="secondary cancel-finance-popup">Cancelar</button><button class="primary">Salvar alterações</button></div></form>`;document.body.append(popup);popup.querySelector('.cancel-finance-popup').onclick=()=>popup.remove();const description=popup.querySelector('#editFinanceDescription'),kind=popup.querySelector('#editFinanceKind'),note=popup.querySelector('#editFinanceAutoKind'),syncKind=()=>{const automatic=automaticCashExpense(description.value);if(automatic)kind.value='Saída';kind.disabled=automatic;note.hidden=!automatic};description.addEventListener('input',syncKind);syncKind();popup.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.submitter,automatic=automaticCashExpense(description.value),amount=Number(popup.querySelector('#editFinanceAmount').value),luizinhoSettlement=confirmLuizinhoSettlement(description.value,amount,true);button.disabled=true;button.textContent='Salvando…';try{await updateFinanceRecord(record.id,{category:'Fluxo de caixa',kind:automatic?'Saída':kind.value,description:description.value.trim(),amount,dueDate:popup.querySelector('#editFinanceDate').value,status:'Realizado',paymentType:popup.querySelector('#editFinanceAccount').value,mechanic:record.mechanic,reference:record.reference,luizinhoSettlement});records=await readFinance();activeCashAccount=popup.querySelector('#editFinanceAccount').value;popup.remove();await loadDashboard()}catch(error){button.disabled=false;button.textContent='Salvar alterações';alert(error.message)}}}

function openPayableEditPopup(id){const record=records.find(item=>item.id===id&&item.category==='Conta a pagar');if(!record)return;const settled=record.status==='Realizado',info=payablePaymentInfo(record);document.querySelector('.finance-popup')?.remove();const popup=document.createElement('div');popup.className='check-popup finance-popup';popup.innerHTML=`<form class="check-popup-card"><span class="eyebrow">EDITAR CONTA A PAGAR</span><h3>${esc(record.description)}</h3>${payableCategoryField(record.payableCategory)}<label><span>Fornecedor / descrição</span><input id="editPayableDescription" value="${esc(record.description)}" required></label><label><span>Data de vencimento</span><input id="editPayableDate" type="date" value="${esc(record.dueDate)}" required></label><label><span>${settled?'Valor registrado':'Saldo restante'}</span><input id="editPayableAmount" type="number" min="0.01" step="0.01" value="${Number(settled?info.original:record.amount).toFixed(2)}" ${settled?'disabled':'required'}></label>${info.paid?`<p>Já pago: <b>${money(info.paid)}</b>. Os pagamentos lançados no caixa não serão alterados.</p>`:''}<div class="check-popup-actions"><button type="button" class="secondary cancel-finance-popup">Cancelar</button><button class="primary">Salvar alterações</button></div></form>`;document.body.append(popup);popup.querySelector('.cancel-finance-popup').onclick=()=>popup.remove();popup.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent='Salvando…';try{await updateFinanceRecord(record.id,{category:'Conta a pagar',payableCategory:popup.querySelector('#payableCategory').value,kind:'Saída',description:popup.querySelector('#editPayableDescription').value.trim(),amount:settled?record.amount:Number(popup.querySelector('#editPayableAmount').value),dueDate:popup.querySelector('#editPayableDate').value,status:record.status,paymentType:record.paymentType,mechanic:record.mechanic});records=await readFinance();popup.remove();renderArea('Conta a pagar')}catch(error){button.disabled=false;button.textContent='Salvar alterações';alert(error.message)}}}

