  $('#content').innerHTML=`<button class="backlink" id="backAdmin">← Voltar ao financeiro</button><section class="form-card finance-form"><div class="form-head"><i>⚙</i><div><span class="eyebrow">EQUIPE DA OFICINA</span><h3>Cadastro de mecânicos</h3><p>Os mecânicos ativos aparecem nas O.S., nos serviços e nas comissões.</p></div></div><form id="mechanicForm"><label><span>Nome do mecânico</span><input id="mechanicName" autocomplete="name" maxlength="80" placeholder="Nome completo" required></label><button class="primary wide">Salvar mecânico</button></form><div class="table-card finance-table"><table><thead><tr><th>Mecânico</th><th>Status</th><th></th></tr></thead><tbody>${mechanics.map(item=>`<tr><td><b>${esc(item.name)}</b></td><td>${item.active?'Ativo':'Inativo'}</td><td><button class="${item.active?'secondary':'primary'} toggle-mechanic" data-name="${esc(item.name)}" data-active="${item.active?'false':'true'}">${item.active?'Desativar':'Ativar'}</button></td></tr>`).join('')}</tbody></table></div></section>`;
