function openPartnerRatePopup(){if(!financeOwner())return;document.querySelector('.partner-rate-popup')?.remove();const currentWeek=commissionWeek(localDateOnly(new Date())),rates=partnerRatesForDate(currentWeek.start),popup=document.createElement('div');popup.className='check-popup finance-popup partner-rate-popup';popup.innerHTML=`<form class="check-popup-card"><span class="eyebrow">CONFIGURAÇÃO RESTRITA</span><h3>Alterar comissões dos sócios</h3><p>Estes percentuais recalculam todos os valores ainda em aberto, inclusive saldos acumulados de semanas anteriores. Pagamentos já arquivados não são alterados. Os textos continuarão mostrando Fabiano 25% e Marcelino 20%.</p><div class="grid two"><label><span>Comissão real de Fabiano (%)</span><input id="partnerRateFabiano" type="number" min="0" max="100" step="0.01" value="${(rates.Fabiano*100).toFixed(2)}" required></label><label><span>Comissão real de Marcelino (%)</span><input id="partnerRateMarcelino" type="number" min="0" max="100" step="0.01" value="${(rates.Marcelino*100).toFixed(2)}" required></label></div><div class="access-restricted-note">Configuração visível somente para o proprietário.</div><div class="check-popup-actions"><button type="button" class="secondary cancel-partner-rates">Cancelar</button><button class="primary">Salvar alteração oculta</button></div></form>`;popup.querySelector('.cancel-partner-rates').onclick=()=>popup.remove();popup.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.submitter,fabiano=Number(popup.querySelector('#partnerRateFabiano').value),marcelino=Number(popup.querySelector('#partnerRateMarcelino').value);if(!Number.isFinite(fabiano)||!Number.isFinite(marcelino)||fabiano<0||fabiano>100||marcelino<0||marcelino>100)return alert('Informe percentuais entre 0 e 100.');button.disabled=true;button.textContent='Salvando…';try{partnerRateWeeks=await savePartnerCommissionRates(currentWeek.start,{Fabiano:fabiano/100,Marcelino:marcelino/100});popup.remove();renderArea('Comissões sócios');alert('Percentuais aplicados aos valores em aberto. Os pagamentos arquivados foram preservados.')}catch(error){button.disabled=false;button.textContent='Salvar alteração oculta';alert(error.message)}};document.body.append(popup)}
function usageTime(seconds){seconds=Math.max(0,Math.round(Number(seconds)||0));const hours=Math.floor(seconds/3600),minutes=Math.floor(seconds%3600/60),rest=seconds%60;if(hours)return`${hours}h ${minutes}min`;if(minutes)return`${minutes}min ${rest}s`;return`${rest}s`}
const usageDate=value=>value?new Date(value).toLocaleString('pt-BR'):'—';
async function openUserUsage(user){document.querySelector('.user-access-popup')?.remove();const popup=document.createElement('div');popup.className='check-popup finance-popup user-access-popup';popup.innerHTML=`<div class="check-popup-card"><span class="eyebrow">HISTÓRICO DE ACESSOS</span><h3>${esc(user.name)}</h3><p>${esc(user.email)}</p><div class="empty user-access-loading"><div>◌</div><h3>Carregando acessos…</h3></div><button type="button" class="secondary wide close-user-access">Fechar</button></div>`;popup.querySelector('.close-user-access').onclick=()=>popup.remove();document.body.append(popup);try{const rows=await readUserUsage(user.email),total=rows.reduce((sum,row)=>sum+row.activeSeconds,0),last=rows.reduce((latest,row)=>!latest||new Date(row.lastSeenAt)>new Date(latest)?row.lastSeenAt:latest,''),now=Date.now(),body=rows.map(row=>{const online=!row.endedAt&&now-new Date(row.lastSeenAt).getTime()<90000,status=online?'Ativo agora':row.endedAt?'Encerrado':'Interrompido';return`<tr><td>${usageDate(row.startedAt)}</td><td>${usageDate(row.lastSeenAt)}</td><td>${row.endedAt?usageDate(row.endedAt):'—'}</td><td><b>${usageTime(row.activeSeconds)}</b></td><td><span class="status ${online?'done':'pending'}">${status}</span></td></tr>`}).join(''),card=popup.querySelector('.check-popup-card');card.querySelector('.user-access-loading').remove();card.querySelector('.close-user-access').insertAdjacentHTML('beforebegin',`<div class="finance-summary user-access-summary"><article><span>Quantidade de acessos</span><b>${rows.length}</b></article><article><span>Tempo ativo acumulado</span><b>${usageTime(total)}</b></article><article><span>Último acesso</span><b>${last?usageDate(last):'Nenhum acesso registrado'}</b></article></div><div class="table-card finance-table user-access-table"><table><thead><tr><th>Entrada</th><th>Última atividade</th><th>Saída</th><th>Tempo ativo</th><th>Status</th></tr></thead><tbody>${body||'<tr><td colspan="5">Nenhum acesso registrado após a ativação deste histórico.</td></tr>'}</tbody></table></div>`)}catch(error){popup.querySelector('.user-access-loading').innerHTML=`<h3>Não foi possível carregar</h3><p>${esc(error.message)}</p>`}}
function openUserManager(){
  const mechanicOptions=`<option value="" disabled selected>Selecione a agenda</option>`+agendaMechanics().map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('');
  $('#content').innerHTML=`<button class="backlink" id="backAdmin">← Voltar ao financeiro</button><section class="form-card finance-form"><div class="form-head"><i>♙</i><div><span class="eyebrow">ACESSOS DO APLICATIVO</span><h3>Gerenciar usuários</h3><p>Cadastre usuários e determine o que cada um pode acessar.</p></div></div><button type="button" class="secondary wide" id="editPartnerRates">Alterar comissões dos sócios</button><form id="newManagedUser"><div class="grid two"><label><span>Nome</span><input id="managedUserName" required></label><label><span>E-mail</span><input id="managedUserEmail" type="email" required></label><label><span>Senha inicial</span><input id="managedUserPassword" type="password" minlength="6" required></label><label><span>Agenda individual</span><select id="managedUserMechanic" required>${mechanicOptions}</select></label></div><h4>Permissões iniciais</h4><div class="checkgrid" id="newUserPermissions">${userPermissionChecks({permissions:{accessApp:true,createEntries:true,editOrders:true,manageValues:false,viewDelivered:true,readyOrders:false,viewFinance:false}})}</div><button class="primary wide">Adicionar usuário</button></form><div class="managed-users-list">${managedUsers.map(user=>`<article class="detail managed-user-card" data-user-email="${esc(user.email)}"><div class="finance-area-head"><div><h3>${esc(user.name)}</h3><p>${esc(user.email)} · ${user.active?'Ativo':'Acesso bloqueado'} · <span class="status ${user.permissions?.viewFinance?'done':'pending'}">Financeiro ${user.permissions?.viewFinance?'liberado':'bloqueado'}</span></p></div><div class="finance-row-actions">${user.email!==FINANCE_EMAIL?'<button class="secondary view-user-access">Ver acessos</button>':''}<button class="${user.permissions?.viewFinance?'danger':'primary'} toggle-user-finance" ${user.email===FINANCE_EMAIL?'disabled':''}>${user.permissions?.viewFinance?'Bloquear Financeiro':'Liberar Financeiro'}</button><button class="${user.active?'danger':'primary'} toggle-user-access" ${user.email===FINANCE_EMAIL?'disabled':''}>${user.active?'Bloquear acesso':'Liberar acesso'}</button></div></div><label><span>Agenda individual</span><select class="managed-user-mechanic" ${user.email===FINANCE_EMAIL?'disabled':''}>${user.email===FINANCE_EMAIL?'<option value="">Todas as agendas · proprietário</option>':`${user.agendaMechanic?'':`<option value="" selected>Sem agenda individual</option>`}${agendaMechanics().map(name=>`<option value="${esc(name)}" ${user.agendaMechanic===name?'selected':''}>${esc(name)}</option>`).join('')}`}</select></label><div class="checkgrid">${userPermissionChecks(user)}</div><div class="access-restricted-note">Financeiro liberado para outros usuários é sempre somente leitura. Exclusivas do proprietário: alterar o Financeiro, excluir O.S., fechamento/entrega e gerenciar usuários.</div><button class="secondary save-user-permissions">Salvar permissões</button></article>`).join('')}</div></section>`;
  $('#backAdmin').onclick=loadDashboard;
  $('#editPartnerRates').onclick=openPartnerRatePopup;
  $('#newManagedUser').onsubmit=async event=>{event.preventDefault();const button=event.submitter,permissions=Object.fromEntries([...event.currentTarget.querySelectorAll('[data-user-permission]')].map(input=>[input.dataset.userPermission,input.checked]));button.disabled=true;button.textContent='Cadastrando…';try{managedUsers=await createManagedUser({name:$('#managedUserName').value,email:$('#managedUserEmail').value,password:$('#managedUserPassword').value,agendaMechanic:$('#managedUserMechanic').value,permissions});openUserManager();alert('Usuário cadastrado e permissões salvas.')}catch(error){button.disabled=false;button.textContent='Adicionar usuário';alert(error.message)}};
  document.querySelectorAll('.managed-user-card').forEach(card=>{const email=card.dataset.userEmail,user=managedUsers.find(item=>item.email===email);card.querySelector('.view-user-access')?.addEventListener('click',()=>openUserUsage(user));card.querySelector('.toggle-user-finance').onclick=async event=>{event.currentTarget.disabled=true;event.currentTarget.textContent='Salvando…';try{managedUsers=await updateManagedUser(email,{permissions:{viewFinance:!user.permissions?.viewFinance}});openUserManager()}catch(error){event.currentTarget.disabled=false;event.currentTarget.textContent=user.permissions?.viewFinance?'Bloquear Financeiro':'Liberar Financeiro';alert(error.message)}};card.querySelector('.toggle-user-access').onclick=async event=>{event.currentTarget.disabled=true;try{managedUsers=await updateManagedUser(email,{active:!user.active,permissions:{accessApp:!user.active}});openUserManager()}catch(error){event.currentTarget.disabled=false;alert(error.message)}};card.querySelector('.save-user-permissions').onclick=async event=>{const permissions=Object.fromEntries([...card.querySelectorAll('[data-user-permission]')].map(input=>[input.dataset.userPermission,input.checked])),agenda=card.querySelector('.managed-user-mechanic').value;event.currentTarget.disabled=true;event.currentTarget.textContent='Salvando…';try{managedUsers=await updateManagedUser(email,{agendaMechanic:agenda,permissions});openUserManager()}catch(error){event.currentTarget.disabled=false;event.currentTarget.textContent='Salvar permissões';alert(error.message)}}})
}
function closingMonthLabel(value){const[year,month]=String(value).split('-');return new Date(Number(year),Number(month)-1,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}
function previousClosingMonth(value){const[year,month]=String(value).split('-').map(Number),previous=new Date(year,month-2,1);return`${previous.getFullYear()}-${String(previous.getMonth()+1).padStart(2,'0')}`}
function monthlyClosingData(month=activeClosingMonth){const orders=localOrders();return summarizeMonthlyClosing({month,orders,records,suppliers:supplierSettlements,profitEvents:cashProfitEvents(),orderProfits:orders.filter(order=>order.status==='Entregue').map(orderProfit),partnerNames:Object.keys(PARTNER_DISPLAY_RATES)})}
function closingTable(rows,columns,empty){return`<div class="table-card finance-table monthly-closing-table"><table><thead><tr>${columns.map(column=>`<th>${column.label}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${columns.map(column=>`<td>${column.render(row)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${columns.length}">${empty}</td></tr>`}</tbody></table></div>`}
function monthlyClosingHtml(summary){const growth=summary.growth===null?'Sem base anterior':`${summary.growth>=0?'+':''}${summary.growth.toLocaleString('pt-BR',{maximumFractionDigits:1})}%`,growthClass=summary.growth===null?'':summary.growth>=0?'positive':'negative',mechanicColumns=[{label:'Mecânico',render:item=>`<b>${esc(item.name)}</b>`},{label:'Carros executados',render:item=>item.carCount},{label:'Produção',render:item=>money(item.production)},{label:'Faturamento',render:item=>money(item.billing)},{label:'Lucro',render:item=>money(item.profit)},{label:'Ticket médio',render:item=>money(item.ticketAverage)},{label:'Comissão',render:item=>money(item.commission)}],supplierColumns=[{label:'Fornecedor',render:item=>`<b>${esc(item.name)}</b>`},{label:'Compras',render:item=>money(item.amount)},{label:'Créditos por devolução',render:item=>item.credits?money(item.credits):'—'}],partnerColumns=[{label:'Sócio',render:item=>`<b>${esc(item.name)}</b>`},{label:'Comissão',render:item=>money(item.commission)}],paymentColumns=[{label:'Tipo de pagamento recebido',render:item=>`<b>${esc(item.name)}</b>`},{label:'Valor',render:item=>money(item.amount)}];return`<div class="monthly-closing-scroll"><div class="finance-summary monthly-closing-summary"><article><span>O.S. entregues</span><b>${summary.deliveredCount}</b></article><article><span>Clientes novos</span><b>${summary.newClients}</b></article><article><span>Ticket médio</span><b>${money(summary.ticketAverage)}</b></article><article class="finance-summary-total"><span>Valor total faturado</span><b>${money(summary.billed)}</b></article><article><span>Total recebido</span><b>${money(summary.received)}</b></article><article><span>Compras de peças</span><b>${money(summary.purchasesTotal)}</b></article><article><span>Contas pagas</span><b>${money(summary.paidAccounts)}</b></article><article><span>Crescimento</span><b class="monthly-growth ${growthClass}">${growth}</b><small>Comparado com ${esc(closingMonthLabel(previousClosingMonth(summary.month)))}</small></article><article class="finance-summary-total"><span>Lucro total</span><b>${money(summary.totalProfit)}</b></article><article class="finance-summary-total"><span>Lucro líquido</span><b>${money(summary.netProfit)}</b></article><article><span>Lucro nas peças</span><b>${money(summary.partsProfit)}</b></article><article><span>Lucro na mão de obra</span><b>${money(summary.laborProfit)}</b></article></div><div class="monthly-closing-grids"><section><h4>Produção e resultados por mecânico</h4><p class="monthly-closing-note">Carros contados uma vez por mecânico. Faturamento e lucro são rateados pela participação nos serviços da O.S.</p>${closingTable(summary.mechanics,mechanicColumns,'Nenhuma produção no mês.')}</section><section><h4>Compras por fornecedor</h4>${closingTable(summary.purchases,supplierColumns,'Nenhuma compra de peças no mês.')}</section><section><h4>Comissões dos sócios</h4>${closingTable(summary.partners,partnerColumns,'Nenhuma comissão de sócio no mês.')}</section><section><h4>Pagamentos recebidos</h4>${closingTable(summary.paymentTypes,paymentColumns,'Nenhum recebimento de O.S. no mês.')}</section></div></div>`}
function closeMonthlyClosing(){document.querySelector('.monthly-closing-popup')?.remove();document.body.classList.remove('modal-open')}
function renderMonthlyClosing(popup){const summary=monthlyClosingData(),body=popup.querySelector('.monthly-closing-body'),label=popup.querySelector('.monthly-closing-title');if(label)label.textContent=closingMonthLabel(activeClosingMonth);if(body)body.innerHTML=monthlyClosingHtml(summary)}
function openMonthlyClosing(){closeMonthlyClosing();const popup=document.createElement('div');popup.className='check-popup finance-popup monthly-closing-popup';popup.innerHTML=`<div class="check-popup-card"><div class="commission-window-head monthly-closing-head"><div><span class="eyebrow">PAINEL ADMINISTRATIVO</span><h3>Fechamento mensal · <span class="monthly-closing-title"></span></h3><p>Resultados das O.S. entregues no mês, com contas e compras registradas no período.</p></div><label><span>Mês</span><input class="monthly-closing-month" type="month" value="${esc(activeClosingMonth)}"></label></div><div class="monthly-closing-body"></div><div class="check-popup-actions"><button type="button" class="primary close-monthly-closing">Fechar</button></div></div>`;popup.querySelector('.monthly-closing-month').onchange=event=>{activeClosingMonth=event.target.value||activeClosingMonth;renderMonthlyClosing(popup)};popup.querySelector('.close-monthly-closing').onclick=closeMonthlyClosing;popup.onclick=event=>{if(event.target===popup)closeMonthlyClosing()};document.body.append(popup);document.body.classList.add('modal-open');renderMonthlyClosing(popup)}
function wireMonthlyClosing(){document.addEventListener('click',event=>{if(event.target.closest?.('#monthlyClosing'))openMonthlyClosing()})}
wireMonthlyClosing();
const backupBase64=text=>{const bytes=new TextEncoder().encode(text);let binary='';for(let index=0;index<bytes.length;index+=32768)binary+=String.fromCharCode(...bytes.subarray(index,index+32768));return btoa(binary)};
async function deliverBackup(text,name){if(window.CortezAndroid?.saveFile){window.CortezAndroid.saveFile(backupBase64(text),name,'application/json');return}const file=new File([text],name,{type:'application/json'});if(navigator.canShare?.({files:[file]})){await navigator.share({title:'Backup Cortez Garage',files:[file]});return}const url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function createBackupFile(){const button=$('#createBackup');button.disabled=true;button.textContent='Preparando backup…';try{const backup=await createOperationalBackup(),stamp=backup.createdAt.replace(/[:.]/g,'-'),name=`cortez-garage-backup-${stamp}.json`,text=JSON.stringify(backup,null,2);await deliverBackup(text,name);localStorage.setItem('cortez-garage-last-backup',backup.createdAt);alert(`Backup criado com ${Object.values(backup.counts).reduce((sum,value)=>sum+value,0)} registros. Guarde o arquivo fora deste aparelho.`);await loadDashboard()}catch(error){button.disabled=false;button.textContent='⇩ Criar backup';if(error?.name!=='AbortError')alert(error.message)}}
async function restoreBackupFile(file){if(!file)return;let backup;try{backup=JSON.parse(await file.text())}catch{return alert('Não foi possível ler este arquivo de backup.')}if(backup?.format!=='cortez-garage-operational-backup')return alert('Este arquivo não é um backup válido do Cortez Garage.');const total=Object.values(backup.counts||{}).reduce((sum,value)=>sum+Number(value||0),0),confirmation=prompt(`ATENÇÃO: a restauração substituirá registros de mesmo código pelos dados do backup de ${new Date(backup.createdAt).toLocaleString('pt-BR')} (${total} registros).\n\nDigite RESTAURAR para continuar.`);if(confirmation!=='RESTAURAR')return;const button=$('#restoreBackup');button.disabled=true;button.textContent='Restaurando…';try{await restoreOperationalBackup(backup);alert('Backup restaurado. O aplicativo será recarregado para buscar os dados recuperados.');location.reload()}catch(error){button.disabled=false;button.textContent='⇧ Restaurar backup';alert(error.message)}}
function wireBackupActions(){$('#createBackup').onclick=createBackupFile;$('#restoreBackup').onclick=()=>$('#restoreBackupFile').click();$('#restoreBackupFile').onchange=event=>{const[file]=event.target.files;restoreBackupFile(file);event.target.value=''}}
async function loadDashboard(){try{if(financeOwner())await reconcileLuizinhoPayables();[records,mechanics,managedUsers,partnerRateWeeks,commissionConfirmations,costPlans,supplierSettlements,supplierStock]=await Promise.all([readFinance(),readMechanics(),readUserAccess(),readPartnerCommissionRates(),financeOwner()?readMechanicCommissionConfirmations():Promise.resolve([]),readCostPlans(),readSupplierSettlements(),readStock()]);const names=activeMechanics();if(!names.includes(activeMechanic))activeMechanic=names[0]||'';$('#content').innerHTML=dashboardHtml();$('#addMechanic').onclick=openMechanicManager;$('#manageUsers').onclick=openUserManager;wireBackupActions();wireCompanyHealth();wireFinancialBalance();wireCommissionSummary();document.querySelectorAll('[data-finance-area]').forEach(button=>button.onclick=()=>renderArea(button.dataset.financeArea));renderArea(activeArea);applyFinanceReadOnly()}catch(error){$('#content').innerHTML=`<div class="empty"><h3>Financeiro indisponível</h3><p>${esc(error.message)}</p></div>`}}
function openFinancePopup(area){document.querySelector('.finance-popup')?.remove();const popup=document.createElement('div'),label=area==='Fluxo de caixa'?'Caixa':area;popup.className='check-popup finance-popup';popup.innerHTML=`<form class="check-popup-card"><h3>Adicionar em ${label}</h3>${area==='Conta a pagar'?payableCategoryField():''}${area==='Comissões'?`<p>Mecânico: <b>${activeMechanic}</b></p>`:''}${area==='Fluxo de caixa'?`<label><span>Caixa</span><select id="financePopupAccount">${CASH_ACCOUNTS.map(name=>`<option ${name===activeCashAccount?'selected':''}>${name}</option>`).join('')}</select></label>`:''}<label><span>Data</span><input id="financePopupDate" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label><span>Registro</span><input id="financePopupDescription" required placeholder="Descrição do lançamento"></label><label><span>Valor</span><input id="financePopupAmount" type="number" min="0.01" step="0.01" required></label>${area==='Fluxo de caixa'?'<label><span>Tipo</span><select id="financePopupKind"><option>Entrada</option><option>Saída</option></select></label><small id="financeAutoKind" hidden>Classificado automaticamente como Saída.</small>':''}<div class="check-popup-actions"><button type="button" class="secondary cancel-finance-popup">Cancelar</button><button class="primary">Salvar</button></div></form>`;document.body.append(popup);popup.querySelector('.cancel-finance-popup').onclick=()=>popup.remove();const description=popup.querySelector('#financePopupDescription'),kind=popup.querySelector('#financePopupKind'),note=popup.querySelector('#financeAutoKind'),syncKind=()=>{if(!kind)return;const automatic=automaticCashExpense(description.value);if(automatic)kind.value='Saída';kind.disabled=automatic;if(note)note.hidden=!automatic};description.addEventListener('input',syncKind);popup.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.submitter,dateValue=popup.querySelector('#financePopupDate').value,amount=Number(popup.querySelector('#financePopupAmount').value),automatic=area==='Fluxo de caixa'&&automaticCashExpense(description.value),luizinhoSettlement=area==='Fluxo de caixa'?confirmLuizinhoSettlement(description.value,amount):undefined;if(luizinhoSettlement===null)return;button.disabled=true;try{await saveFinanceRecord({category:area,payableCategory:area==='Conta a pagar'?popup.querySelector('#payableCategory').value:undefined,kind:area==='Fluxo de caixa'?(automatic?'Saída':kind.value):'Saída',description:description.value.trim(),amount,dueDate:dateValue,status:area==='Fluxo de caixa'?'Realizado':'Pendente',mechanic:area==='Comissões'?activeMechanic:'',paymentType:area==='Fluxo de caixa'?popup.querySelector('#financePopupAccount').value:'',weekStart:area==='Comissões'?monday(dateValue):'',luizinhoSettlement});records=await readFinance();popup.remove();await loadDashboard()}catch(error){button.disabled=false;alert(error.message)}}}
function openFinanceForm(){$('#content').innerHTML=`<button class="backlink" id="backAdmin">← Voltar ao financeiro</button><form class="form-card finance-form" id="financeForm"><div class="form-head"><i>R$</i><div><h3>Novo lançamento</h3><p>Caixa, contas e comissões</p></div></div><div class="grid two"><label><span>Área</span><select id="financeCategory"><option>Fluxo de caixa</option><option>Conta a pagar</option><option>Conta a receber</option><option>Comissões</option></select></label><div id="payableCategoryField" hidden>${payableCategoryField()}</div><label><span>Movimento</span><select id="financeKind"><option>Entrada</option><option>Saída</option></select></label><label><span>Descrição</span><input id="financeDescription" required></label><label><span>Valor</span><input id="financeAmount" type="number" min="0" step="0.01" required></label><label><span>Vencimento/data</span><input id="financeDue" type="date" required></label><label><span>Status</span><select id="financeStatus"><option>Pendente</option><option>Realizado</option></select></label></div><button class="primary wide">Salvar lançamento</button></form>`;$('#backAdmin').onclick=loadDashboard;$('#financeCategory').onchange=event=>{$('#payableCategoryField').hidden=event.target.value!=='Conta a pagar';if(['Conta a pagar','Comissões'].includes(event.target.value))$('#financeKind').value='Saída';if(event.target.value==='Conta a receber')$('#financeKind').value='Entrada'};$('#financeForm').onsubmit=saveFinance}
async function saveFinance(event){event.preventDefault();const button=event.submitter,category=$('#financeCategory').value,description=$('#financeDescription').value.trim(),amount=Number($('#financeAmount').value),luizinhoSettlement=category==='Fluxo de caixa'?confirmLuizinhoSettlement(description,amount):undefined;if(luizinhoSettlement===null)return;button.disabled=true;button.textContent='Salvando…';try{await saveFinanceRecord({category,payableCategory:category==='Conta a pagar'?$('#payableCategory').value:undefined,kind:$('#financeKind').value,description,amount,dueDate:$('#financeDue').value,status:$('#financeStatus').value,luizinhoSettlement});loadDashboard()}catch(error){alert(error.message);button.disabled=false;button.textContent='Salvar lançamento'}}
function openPayableSettlement(record){document.querySelector('.finance-popup')?.remove();const balance=Number(record.amount||0),popup=document.createElement('div');popup.className='check-popup finance-popup';popup.innerHTML=`<form class="check-popup-card"><span class="eyebrow">PAGAR CONTA</span><h3>${esc(record.description)}</h3><p>Saldo atual: <b>${money(balance)}</b>. Informe o valor total ou apenas a parcela paga agora.</p><label><span>Caixa utilizado</span><select id="payableCashAccount" required>${CASH_ACCOUNTS.map(name=>`<option ${name===activeCashAccount?'selected':''}>${name}</option>`).join('')}</select></label><label><span>Valor pago agora</span><input id="payablePaidAmount" type="number" min="0.01" max="${balance.toFixed(2)}" step="0.01" value="${balance.toFixed(2)}" required></label><p id="payablePaymentResult">Pagamento total: a conta será quitada.</p><div class="check-popup-actions"><button type="button" class="secondary cancel-finance-popup">Cancelar</button><button class="primary">Quitar conta e lançar no caixa</button></div></form>`;document.body.append(popup);popup.querySelector('.cancel-finance-popup').onclick=()=>popup.remove();const input=popup.querySelector('#payablePaidAmount'),result=popup.querySelector('#payablePaymentResult'),submit=popup.querySelector('button.primary'),sync=()=>{const amount=Number(input.value||0),remaining=Math.max(0,balance-amount),partial=remaining>.01;result.innerHTML=partial?`Pagamento parcial. Saldo restante: <b>${money(remaining)}</b>.`:'Pagamento total: a conta será quitada.';submit.textContent=partial?'Registrar pagamento parcial':'Quitar conta e lançar no caixa'};input.addEventListener('input',sync);popup.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.submitter,account=popup.querySelector('#payableCashAccount').value,amount=Number(input.value);button.disabled=true;button.textContent='Registrando…';try{const payment=await settlePayable(record.id,account,amount);activeCashAccount=account;records=await readFinance();popup.remove();renderArea('Conta a pagar');alert(payment.settled?'Conta quitada e saída lançada no caixa.':`Pagamento parcial registrado. Saldo restante: ${money(payment.remaining)}.`)}catch(error){button.disabled=false;sync();alert(error.message)}}}
function openReceivableSettlement(record){document.querySelector('.finance-popup')?.remove();const popup=document.createElement('div');popup.className='check-popup finance-popup';popup.innerHTML=`<form class="check-popup-card"><span class="eyebrow">RECEBER CONTA</span><h3>${esc(record.description)}</h3><p>Valor a receber: <b>${money(record.amount)}</b>. Escolha em qual caixa o valor entrou.</p><label><span>Caixa de entrada</span><select id="receivableCashAccount" required>${CASH_ACCOUNTS.map(name=>`<option ${name===activeCashAccount?'selected':''}>${name}</option>`).join('')}</select></label><div class="check-popup-actions"><button type="button" class="secondary cancel-finance-popup">Cancelar</button><button class="primary">Dar baixa e lançar no caixa</button></div></form>`;document.body.append(popup);popup.querySelector('.cancel-finance-popup').onclick=()=>popup.remove();popup.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.submitter,account=popup.querySelector('#receivableCashAccount').value;button.disabled=true;button.textContent='Registrando…';try{await markFinanceDone(record.id,account);activeCashAccount=account;popup.remove();await loadDashboard();alert(`Conta recebida e entrada lançada em ${account}.`)}catch(error){button.disabled=false;button.textContent='Dar baixa e lançar no caixa';alert(error.message)}}}
function openCommissionPayment(record){if(!record)return;document.querySelector('.finance-popup')?.remove();const popup=document.createElement('div');popup.className='check-popup finance-popup';popup.innerHTML=`<form class="check-popup-card"><span class="eyebrow">PAGAR COMISSÃO</span><h3>${esc(record.mechanic||'Mecânico')}</h3><p>${esc(record.description)} no valor de <b>${money(record.amount)}</b>.</p><label><span>Caixa utilizado</span><select id="commissionCashAccount" required>${CASH_ACCOUNTS.map(name=>`<option ${name===activeCashAccount?'selected':''}>${name}</option>`).join('')}</select></label><div class="check-popup-actions"><button type="button" class="secondary cancel-finance-popup">Cancelar</button><button class="primary">Pagar e lançar no caixa</button></div></form>`;document.body.append(popup);popup.querySelector('.cancel-finance-popup').onclick=()=>popup.remove();popup.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.submitter,account=popup.querySelector('#commissionCashAccount').value;button.disabled=true;button.textContent='Pagando…';try{await payCommission(record.id,account);activeCashAccount=account;records=await readFinance();popup.remove();renderArea('Comissões');alert(`Comissão paga e saída lançada em ${account}.`)}catch(error){button.disabled=false;button.textContent='Pagar e lançar no caixa';alert(error.message)}}}
async function markPaid(id){const record=records.find(item=>item.id===id);if(record?.category==='Conta a pagar')return openPayableSettlement(record);if(record?.category==='Conta a receber')return openReceivableSettlement(record);if(!confirm('Marcar este lançamento como realizado?'))return;try{await markFinanceDone(id);await loadDashboard()}catch(error){alert(error.message)}}
function install(){if(!financeVisible()){document.querySelectorAll('.admin-route').forEach(button=>button.remove());return}const label=financeOwner()?'Administrativo':'Financeiro';const nav=document.querySelector('aside nav');if(nav&&!nav.querySelector('.admin-route')){const b=document.createElement('button');b.className='admin-route';b.innerHTML=`<i>◆</i>${label}`;b.onclick=openAdmin;nav.append(b)}const mobile=document.querySelector('.mobile-nav');if(mobile&&!mobile.querySelector('.admin-route')){const b=document.createElement('button');b.className='admin-route';b.innerHTML=`<i>◆</i><span>${financeOwner()?'Admin':'Financeiro'}</span>`;b.onclick=openAdmin;mobile.append(b)}}
new MutationObserver(()=>{install();applyFinanceReadOnly()}).observe(document.querySelector('#app'),{childList:true,subtree:true});install();
addEventListener('cortez:user-access-updated',()=>{const financeOpen=Boolean(document.querySelector('.admin-route.active'));install();if(!financeVisible()&&financeOpen){document.querySelector('.finance-popup')?.remove();document.querySelector('[data-route="dashboard"]')?.click()}});
document.addEventListener('cortez:luizinho-returns-updated',async()=>{if(activeArea!=='Acerto fornecedores'||activeSupplier!=='luizinho')return;[records,supplierSettlements,supplierStock]=await Promise.all([readFinance(),readSupplierSettlements(),readStock()]);renderArea('Acerto fornecedores')});




